Subtracting $\mu$ moves the centre to $0$, and dividing by $\sigma$ makes the standard deviation $1$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.3cm, y=1cm]
\draw[thick] plot[domain=-3.2:3.2, samples=90, smooth, variable=\x] ({\x},{2.2*exp(-\x*\x/2)});
\draw[->] (-3.6,0) -- (3.9,0) node[right] {$x$};
\draw (0,0) -- (0,-0.12) node[below, font=\small] {$\mu$};
\draw (-1,0) -- (-1,-0.12) node[below, font=\small] {$\mu-\sigma$};
\draw (1,0) -- (1,-0.12) node[below, font=\small] {$\mu+\sigma$};
\draw[->] (-3.6,-1.7) -- (3.9,-1.7) node[right] {$z$};
\draw (0,-1.7) -- (0,-1.82) node[below, font=\small] {$0$};
\draw (-1,-1.7) -- (-1,-1.82) node[below, font=\small] {$-1$};
\draw (1,-1.7) -- (1,-1.82) node[below, font=\small] {$1$};
\node[font=\small] at (0,-0.95) {$z=\frac{x-\mu}{\sigma}$};
\end{tikzpicture}
[/tikz]
